CREATE FUNCTION public.documento_pode_imprimir() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND (public.has_role(auth.uid(),'company_admin') OR private.is_super_admin() OR EXISTS(SELECT 1 FROM public.sector_users su JOIN public.company_sectors cs ON cs.id=su.sector_id AND coalesce(cs.is_active,true) JOIN public.access_profiles ap ON ap.id=ANY(cs.allowed_profile_ids::text[]) AND coalesce(ap.is_active,true) WHERE su.user_id=auth.uid() AND ap.company_id=public.get_user_company_id(auth.uid()) AND (coalesce(ap.permissions->'reception','[]'::jsonb)?'view' OR coalesce(ap.permissions->'lab_technical','[]'::jsonb)?'view'))) $$;
REVOKE ALL ON FUNCTION public.documento_pode_imprimir() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.documento_pode_imprimir() TO authenticated;
CREATE FUNCTION public.documento_modelo_validar() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.name IS NULL OR length(btrim(NEW.name)) NOT BETWEEN 2 AND 120 OR NEW.type IS NULL OR NEW.type NOT IN ('declaracao','termo','outro') OR NEW.default_format IS NULL OR NEW.default_format NOT IN ('A4','A5') OR NEW.signature_mode IS NULL OR NEW.signature_mode NOT IN ('paciente','responsavel','empresa','paciente_empresa','responsavel_empresa','paciente_responsavel') OR length(coalesce(NEW.body_html,'')) NOT BETWEEN 1 AND 100000 OR length(btrim(regexp_replace(NEW.body_html,'<[^>]*>','','g'))) = 0 THEN RAISE EXCEPTION 'Dados do modelo inválidos'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.documento_modelo_validar() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER documento_modelo_validacao BEFORE INSERT OR UPDATE ON public.document_templates FOR EACH ROW EXECUTE FUNCTION public.documento_modelo_validar();
CREATE FUNCTION public.documento_log_validar() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT public.documento_pode_imprimir() THEN RAISE EXCEPTION 'Sem permissão para imprimir'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.documento_log_validar() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER documento_log_validacao BEFORE INSERT ON public.document_print_logs FOR EACH ROW EXECUTE FUNCTION public.documento_log_validar();